import express, { Express } from "express";
import { CancelOrderUseCase } from "../application/cancel-order-use-case";
import { GetOrderUseCase } from "../application/get-order-use-case";
import { ListOrdersByStateUseCase } from "../application/list-orders-by-state-use-case";
import { ListStockLevelsUseCase } from "../application/list-stock-levels-use-case";
import { PlaceOrderUseCase } from "../application/place-order-use-case";
import { TransitionOrderUseCase } from "../application/transition-order-use-case";
import { Product } from "../domain/product";
import { StockReservationService } from "../domain/stock-reservation-service";
import { errorHandlerMiddleware } from "./error-handler-middleware";
import { InMemoryOrderRepository } from "./in-memory-order-repository";
import { InMemoryProductRepository } from "./in-memory-product-repository";
import { OrderController } from "./order-controller";
import { StockController } from "./stock-controller";
import { UuidIdGenerator } from "./uuid-id-generator";

export function createApp(catalogue: readonly Product[]): Express {
  const orders = new InMemoryOrderRepository();
  const products = new InMemoryProductRepository(catalogue);
  const reservations = new StockReservationService(products);

  const orderController = new OrderController(
    new PlaceOrderUseCase(orders, reservations, new UuidIdGenerator()),
    new TransitionOrderUseCase(orders),
    new CancelOrderUseCase(orders, reservations),
    new ListOrdersByStateUseCase(orders),
    new GetOrderUseCase(orders),
  );
  const stockController = new StockController(new ListStockLevelsUseCase(products));

  const app = express();
  app.use(express.json());
  app.use("/orders", orderController.routes());
  app.use("/stock", stockController.routes());
  app.use(errorHandlerMiddleware);
  return app;
}

