import { Request, Response, Router } from "express";
import { CancelOrderUseCase } from "../application/cancel-order-use-case";
import { PlaceOrderRequest } from "../application/dtos";
import { GetOrderUseCase } from "../application/get-order-use-case";
import { ListOrdersByStateUseCase } from "../application/list-orders-by-state-use-case";
import { PlaceOrderUseCase } from "../application/place-order-use-case";
import { TransitionOrderUseCase } from "../application/transition-order-use-case";
import { InvalidRequestError } from "../domain/domain-errors";
import { OrderState, isOrderState } from "../domain/order-state";

const TRANSITION_ACTIONS: Record<string, OrderState> = {
  pay: "paid",
  pack: "packed",
  ship: "shipped",
  deliver: "delivered",
};

export class OrderController {
  constructor(
    private readonly placeOrder: PlaceOrderUseCase,
    private readonly transitionOrder: TransitionOrderUseCase,
    private readonly cancelOrder: CancelOrderUseCase,
    private readonly listOrders: ListOrdersByStateUseCase,
    private readonly getOrder: GetOrderUseCase,
  ) {}

  routes(): Router {
    const router = Router();
    router.post("/", (req, res) => this.place(req, res));
    router.get("/", (req, res) => this.list(req, res));
    router.get("/:id", (req, res) => this.get(req, res));
    router.post("/:id/cancel", (req, res) => this.cancel(req, res));
    router.post("/:id/:action", (req, res) => this.transition(req, res));
    return router;
  }

  private async place(req: Request, res: Response): Promise<void> {
    res.status(201).json(await this.placeOrder.execute(this.parsePlaceRequest(req.body)));
  }

  private async list(req: Request, res: Response): Promise<void> {
    const state = req.query.state;
    if (!isOrderState(state)) throw new InvalidRequestError("Query parameter 'state' is invalid");
    res.json(await this.listOrders.execute(state));
  }

  private async get(req: Request, res: Response): Promise<void> {
    res.json(await this.getOrder.execute(String(req.params.id)));
  }

  private async cancel(req: Request, res: Response): Promise<void> {
    res.json(await this.cancelOrder.execute(String(req.params.id)));
  }

  private async transition(req: Request, res: Response): Promise<void> {
    const target = TRANSITION_ACTIONS[String(req.params.action)];
    if (!target) throw new InvalidRequestError(`Unknown action '${String(req.params.action)}'`);
    res.json(await this.transitionOrder.execute(String(req.params.id), target));
  }

  private parsePlaceRequest(body: unknown): PlaceOrderRequest {
    const data = (body ?? {}) as { customerId?: unknown; items?: unknown };
    if (typeof data.customerId !== "string" || !Array.isArray(data.items)) {
      throw new InvalidRequestError("Body must contain customerId and items");
    }
    const items = data.items.map((raw: unknown) => {
      const item = (raw ?? {}) as { productId?: unknown; quantity?: unknown };
      if (typeof item.productId !== "string" || typeof item.quantity !== "number") {
        throw new InvalidRequestError("Each item needs productId and numeric quantity");
      }
      return { productId: item.productId, quantity: item.quantity };
    });
    return { customerId: data.customerId, items };
  }
}

